     3	/* power on a tile/block within ACP */
     4	static int acp_resume_tile(void *cgs_dev, int tile)
     5	{
     6		u32 val = 0;
     7		u32 count = 0;
     8	
     9		if ((tile  < ACP_TILE_P1) || (tile > ACP_TILE_DSP2)) {
    10			pr_err("Invalid ACP tile to resume\n");
    11			return -1;
    12		}
    13	
    14		val = cgs_read_register(cgs_dev, mmACP_PGFSM_READ_REG_0 + tile);
    15		val = val & ACP_TILE_ON_MASK;
    16	
    17		if (val != 0x0) {
    18			cgs_write_register(cgs_dev, mmACP_PGFSM_CONFIG_REG,
    19						0x600 + tile);
    20			count = ACP_TIMEOUT_LOOP;
    21			while (true) {
    22				val = cgs_read_register(cgs_dev, mmACP_PGFSM_READ_REG_0
    23								+ tile);
    24				val = val & ACP_TILE_ON_MASK;
    25				if (val == 0x0)
    26					break;
    27				if (--count == 0) {
    28					pr_err("Timeout reading ACP PGFSM status\n");
    29					return -ETIMEDOUT;
    30				}
    31				udelay(100);
    32			}
    33			val = cgs_read_register(cgs_dev, mmACP_PGFSM_RETAIN_REG);
    34			if (tile == ACP_TILE_P1)
    35				val = val & (ACP_TILE_P1_MASK);
    36			else if (tile == ACP_TILE_P2)
    37				val = val & (ACP_TILE_P2_MASK);
    38	
    39			cgs_write_register(cgs_dev, mmACP_PGFSM_RETAIN_REG, val);
    40		}
    41		return 0;
    42	}
    43	
    44	struct acp_pm_domain {
    45		void *cgs_dev;
    46		struct generic_pm_domain gpd;
    47	};
    48	
    49	static int acp_poweroff(struct generic_pm_domain *genpd)
    50	{
    51		int i, ret;
    52		struct acp_pm_domain *apd;
    53	
    54		apd = container_of(genpd, struct acp_pm_domain, gpd);
    55		if (apd != NULL) {
    56			/* Donot return abruptly if any of power tile fails to suspend.
    57			 * Log it and continue powering off other tile
    58			 */
    59			for (i = 4; i >= 0 ; i--) {
    60				ret = acp_suspend_tile(apd->cgs_dev, ACP_TILE_P1 + i);
    61				if (ret)
    62					pr_err("ACP tile %d tile suspend failed\n", i);
    63			}
    64		}
    65		return 0;
    66	}
    67	
    68	static int acp_poweron(struct generic_pm_domain *genpd)
    69	{
    70		int i, ret;
    71		struct acp_pm_domain *apd;
    72	
    73		apd = container_of(genpd, struct acp_pm_domain, gpd);
    74		if (apd != NULL) {
    75			for (i = 0; i < 2; i++) {
    76				ret = acp_resume_tile(apd->cgs_dev, ACP_TILE_P1 + i);
    77				if (ret) {
    78					pr_err("ACP tile %d resume failed\n", i);
    79					break;
    80				}
    81			}
    82	
    83			/* Disable DSPs which are not going to be used */
    84			for (i = 0; i < 3; i++) {
    85				ret = acp_suspend_tile(apd->cgs_dev, ACP_TILE_DSP0 + i);
    86				/* Continue suspending other DSP, even if one fails */
    87				if (ret)
    88					pr_err("ACP DSP %d suspend failed\n", i);
    89			}
    90		}
    91		return 0;
    92	}
